window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7862dbb43fae541e"]={"versions": [{"id": "FIG-7862dbb43fae541e", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Klassenspezifikation (AUTOSAR MSR/UML-Metamodell-Dokumentationstabelle) für das Metamodell-Element <code>DelegationHWConnection</code> innerhalb des Pakets <code>AUTOSAR Templates::ECUResourceTemplate</code>. Das Diagramm beschreibt die statischen Eigenschaften und Referenzbeziehungen einer Hardware-Delegationsverbindung im Kontext der ECU-Ressourcenbeschreibung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Klasse</strong>: <code>DelegationHWConnection</code>\n</li><li><strong>Paket</strong>: <code>AUTOSAR Templates::ECUResourceTemplate</code>\n</li><li><strong>Basisklasse</strong>: <code>HWConnection</code>\n</li><li><strong>Beschreibung</strong>: Dient zur Verbindung von HWPorts eines HWContainers mit HWPorts der darin enthaltenen HWElements.\n</li><li><strong>Attribute / Rollen</strong>:\n<ul class=\"fig-list\"><li><code>INNER-PORT</code>: Datentyp <code>HWPort</code>, Multiplizität <code>1</code>, Link-Typ <code>reference</code>. Referenziert den Hardware-Port des verbundenen inneren Hardware-Elements (<code>HWElement</code>).\n</li><li><code>OUTER-PORT</code>: Datentyp <code>HWPort</code>, Multiplizität <code>1</code>, Link-Typ <code>reference</code>. Referenziert den Hardware-Port des verbundenen äußeren Hardware-Elements (<code>HWElement</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell-Element ohne dynamische Ablauf- oder Sequenzsemantik. Die Spezifikation definiert eine hierarchische Delegationsbeziehung, bei der zur Laufzeit oder Modellierungszeit Signale bzw. Hardware-Verbindungen zwischen der Port-Grenze eines umfassenden Containers (<code>HWContainer</code>) und den Ports seiner internen Komponenten (<code>HWElements</code>) geroutet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kardinalität und Eindeutigkeit</strong>: Ein bestimmter <code>HWPort</code> darf von genau einer <code>DelegationHWConnection</code> referenziert werden (<code>A single HWPort can only be referenced by exactly one DelegationHWConnection</code>).\n</li><li><strong>Referenzierungsregeln</strong>: Sowohl <code>INNER-PORT</code> als auch <code>OUTER-PORT</code> sind strikte 1:1-Referenzen (<code>Mul. = 1</code>, <code>Link Type = reference</code>).\n</li><li><strong>Modellierungsanwendung</strong>: Verbindungsinstanzen dieses Typs kapseln die interne Hardware-Topologie, indem Ports auf Containerebene nach innen delegiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3666eaad980865b9", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Klassenspezifikation (AUTOSAR MSR/UML-Metamodell-Dokumentationstabelle) für das Metamodell-Element <code>DelegationHWConnection</code> innerhalb des Pakets <code>AUTOSAR Templates::ECUResourceTemplate</code>. Das Diagramm beschreibt die statischen Eigenschaften und Referenzbeziehungen einer Hardware-Delegationsverbindung im Kontext der ECU-Ressourcenbeschreibung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Klasse</strong>: <code>DelegationHWConnection</code>\n</li><li><strong>Paket</strong>: <code>AUTOSAR Templates::ECUResourceTemplate</code>\n</li><li><strong>Basisklasse</strong>: <code>HWConnection</code>\n</li><li><strong>Beschreibung</strong>: Dient zur Verbindung von HWPorts eines HWContainers mit HWPorts der darin enthaltenen HWElements.\n</li><li><strong>Attribute / Rollen</strong>:\n<ul class=\"fig-list\"><li><code>INNER-PORT</code>: Datentyp <code>HWPort</code>, Multiplizität <code>1</code>, Link-Typ <code>reference</code>. Referenziert den Hardware-Port des verbundenen inneren Hardware-Elements (<code>HWElement</code>).\n</li><li><code>OUTER-PORT</code>: Datentyp <code>HWPort</code>, Multiplizität <code>1</code>, Link-Typ <code>reference</code>. Referenziert den Hardware-Port des verbundenen äußeren Hardware-Elements (<code>HWElement</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell-Element ohne dynamische Ablauf- oder Sequenzsemantik. Die Spezifikation definiert eine hierarchische Delegationsbeziehung, bei der zur Laufzeit oder Modellierungszeit Signale bzw. Hardware-Verbindungen zwischen der Port-Grenze eines umfassenden Containers (<code>HWContainer</code>) und den Ports seiner internen Komponenten (<code>HWElements</code>) geroutet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kardinalität und Eindeutigkeit</strong>: Ein bestimmter <code>HWPort</code> darf von genau einer <code>DelegationHWConnection</code> referenziert werden (<code>A single HWPort can only be referenced by exactly one DelegationHWConnection</code>).\n</li><li><strong>Referenzierungsregeln</strong>: Sowohl <code>INNER-PORT</code> als auch <code>OUTER-PORT</code> sind strikte 1:1-Referenzen (<code>Mul. = 1</code>, <code>Link Type = reference</code>).\n</li><li><strong>Modellierungsanwendung</strong>: Verbindungsinstanzen dieses Typs kapseln die interne Hardware-Topologie, indem Ports auf Containerebene nach innen delegiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7862dbb43fae541e", "to": "FIG-3666eaad980865b9", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
